select string_agg(p.proname||'='||substr(md5(pg_get_functiondef(p.oid)),1,10), ' ' order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname in ('hdm_my_entitlements','hdm_plan_of','hdm_plan_row','hdm_send_target','hdm_my_targets','hdm_who_targeted_me','hdm_match_ratings','hdm_extended_analysis','hdm_can_open_chat','hdm_open_chat','hdm_chat_limit_ok','hdm_pair_status') or p.proname like 'hdm_%chat%' or p.proname like 'hdm_%target%')
